use aria2_core::http::auth::AuthConfigFactory;

let mut factory = AuthConfigFactory::new();
let url = url::Url::parse("http://user:pass@example.com/file").unwrap();
let auth = factory.resolve(&url, false, None, None, false);
assert!(auth.is_some());
```

